def write():
 for v,lectures in E.items():
  for lec,pages in lectures.items():
   total=16 if lec=='lecture16' else 8
   rows=[]
   for page in range(1,total+1):
    if lec=='lecture16' and page in L16_ALIAS:rows.append(f'{page}|=lecture15:{L16_ALIAS[page]}');continue
    blocks=pages.get(page)
    if not blocks:
     assert page in (L16_EMPTY if lec=='lecture16' else L17_EMPTY),(v,lec,page);rows.append(f'{page}|');continue
    rows.append(f'{page}|'+' || '.join(' >> '.join([head,*children]) for head,children in blocks))
   (A/f'transcripts-v{v}'/f'{lec}.txt').write_text('\n'.join(rows)+'\n')
 print('wrote',len(E),'editions')
if __name__=='__main__':write()
